<?php
require_once __DIR__ . '/../config/i18n.php';if (session_status() !== PHP_SESSION_ACTIVE) {
    session_start();
}
require_once "../config/database.php";
if (!isset($_SESSION["user_id"]) || ($_SESSION["user_role"] ?? "") !== "teacher") { http_response_code(403); exit("Accès interdit."); }
$teacherId=(int)$_SESSION["user_id"]; $studentId=filter_input(INPUT_GET,"student_id",FILTER_VALIDATE_INT);
$courseId=filter_input(INPUT_GET,"course_id",FILTER_VALIDATE_INT); $courseId=$courseId&&$courseId>0?$courseId:null;
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET["from"]??"")?$_GET["from"]:""; $to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET["to"]??"")?$_GET["to"]:"";
if(!$studentId){http_response_code(400);exit("Étudiant invalide.");}
$courseSql=$courseId?" AND c.id = ?":""; $studentParams=[$teacherId,$studentId]; if($courseId)$studentParams[]=$courseId;
$s=$pdo->prepare("SELECT DISTINCT u.id,u.first_name,u.last_name,u.email FROM users u INNER JOIN enrollments en ON en.user_id=u.id AND en.status IN ('active','completed') INNER JOIN courses c ON c.id=en.course_id AND EXISTS (SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?){$courseSql} WHERE u.id=? AND u.role='student'");
/* Keep the parameter order aligned with teacher, optional course, then student. */
if($courseId){$s->execute([$teacherId,$courseId,$studentId]);}else{$s->execute([$teacherId,$studentId]);}
$student=$s->fetch(PDO::FETCH_ASSOC); if(!$student){http_response_code(404);exit("Étudiant introuvable dans vos formations.");}
$params=[$studentId,$teacherId]; if($courseId)$params[]=$courseId; $date="";
if($from){$date.=" AND lp.updated_at >= ?";$params[]=$from." 00:00:00";} if($to){$date.=" AND lp.updated_at <= ?";$params[]=$to." 23:59:59";}
$less=$pdo->prepare("SELECT c.title course_title,m.title module_title,l.title lesson_title,COALESCE(lp.progress_percent,0) progress_percent,COALESCE(lp.completed,0) completed,COALESCE(lp.total_time_seconds,0) total_time_seconds,COALESCE(lp.last_position,0) last_position,lp.updated_at FROM lesson_progress lp INNER JOIN lessons l ON l.id=lp.lesson_id INNER JOIN modules m ON m.id=l.module_id INNER JOIN courses c ON c.id=m.course_id AND EXISTS (SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?) INNER JOIN enrollments en ON en.user_id=lp.user_id AND en.course_id=c.id AND en.status IN ('active','completed') WHERE lp.user_id=?{$courseSql}{$date} ORDER BY lp.updated_at DESC");
$lessonParams=[$teacherId,$studentId];if($courseId)$lessonParams[]=$courseId;if($from)$lessonParams[]=$from." 00:00:00";if($to)$lessonParams[]=$to." 23:59:59";
$less->execute($lessonParams);$lessons=$less->fetchAll(PDO::FETCH_ASSOC);
$aParams=[$teacherId,$studentId];if($courseId)$aParams[]=$courseId;$adate="";if($from){$adate.=" AND qa.completed_at >= ?";$aParams[]=$from." 00:00:00";}if($to){$adate.=" AND qa.completed_at <= ?";$aParams[]=$to." 23:59:59";}
$q=$pdo->prepare("SELECT 'Quiz' type,q.title,c.title course_title,qa.percentage score,qa.passed,qa.completed_at FROM quiz_attempts qa INNER JOIN quizzes q ON q.id=qa.quiz_id INNER JOIN modules m ON m.id=q.module_id INNER JOIN courses c ON c.id=m.course_id AND EXISTS (SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?) INNER JOIN enrollments en ON en.user_id=qa.user_id AND en.course_id=c.id AND en.status IN ('active','completed') WHERE qa.user_id=? AND qa.completed_at IS NOT NULL{$courseSql}{$adate} UNION ALL SELECT 'Examen',ex.title,c.title,ea.percentage,ea.passed,ea.completed_at FROM exam_attempts ea INNER JOIN exams ex ON ex.id=ea.exam_id INNER JOIN courses c ON c.id=ex.course_id AND EXISTS (SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?) INNER JOIN enrollments en ON en.user_id=ea.user_id AND en.course_id=c.id AND en.status IN ('active','completed') WHERE ea.user_id=? AND ea.completed_at IS NOT NULL".($courseId?" AND c.id = ?":"").($from?" AND ea.completed_at >= ?":"").($to?" AND ea.completed_at <= ?":"")." ORDER BY completed_at DESC");
$qParams=array_merge($aParams,[$teacherId,$studentId]);if($courseId)$qParams[]=$courseId;if($from)$qParams[]=$from." 00:00:00";if($to)$qParams[]=$to." 23:59:59";$q->execute($qParams);$assessments=$q->fetchAll(PDO::FETCH_ASSOC);
$e=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");};$dateFn=function($v){return $v?date("d/m/Y H:i",strtotime($v)):"—";};$totalLessons=count($lessons);$completed=count(array_filter($lessons,function($r){return $r["completed"];}));$minutes=round(array_sum(array_column($lessons,"total_time_seconds"))/60);
if(isset($_GET["download"])){header("Content-Type:text/html; charset=UTF-8");header("Content-Disposition:attachment; filename=\"rapport-progression-".$studentId.".html\"");}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Rapport étudiant - <?=$e($student["first_name"]." ".$student["last_name"])?></title><link rel="stylesheet" href="../assets/css/style.css?v=20260925e"></head><body class="admin-body"><main class="admin-student-report"><div class="report-actions"><a href="results.php">← Retour</a> <button onclick="window.print()">Imprimer / Enregistrer en PDF</button><a href="?<?=http_build_query(array_merge($_GET,["download"=>1]))?>">Télécharger HTML</a></div><h1>Rapport de progression</h1><p><strong><?=$e($student["first_name"]." ".$student["last_name"])?></strong> · <?=$e($student["email"])?></p><p>Généré le <?=date("d/m/Y H:i")?> · Leçons terminées : <?=$completed?> / <?=$totalLessons?> · Temps actif : <?=$minutes?> min</p><h2>Leçons</h2><table><tr><th>Formation</th><th>Module</th><th>Leçon</th><th>Progression</th><th>Temps</th><th>Position</th><th>Dernière activité</th></tr><?php foreach($lessons as $r):?><tr><td><?=$e($r["course_title"])?></td><td><?=$e($r["module_title"])?></td><td><?=$e($r["lesson_title"])?></td><td><?=$e($r["progress_percent"])?>%</td><td><?=round($r["total_time_seconds"]/60)?> min</td><td><?=$e($r["last_position"])?> s</td><td><?=$dateFn($r["updated_at"])?></td></tr><?php endforeach;?></table><h2>Quiz et examens</h2><table><tr><th>Type</th><th>Formation</th><th>Évaluation</th><th>Score</th><th>Statut</th><th>Date</th></tr><?php foreach($assessments as $r):?><tr><td><?=$e($r["type"])?></td><td><?=$e($r["course_title"])?></td><td><?=$e($r["title"])?></td><td><?=$e($r["score"])?>%</td><td><?=$r["passed"]?"Réussi":"À revoir"?></td><td><?=$dateFn($r["completed_at"])?></td></tr><?php endforeach;?></table></main></body></html>


